"""Read-only FIT Ring camera screen/pixel-center audit; no objective/config update."""
from ba021 import *
def main():
 v=next(v for v in load(R/'config/VIEWS.json')if v['video']=='005'and v['role']=='FIT');H=tensor(load(R/'results/B0_RoMa.json')['T'],torch.float64);rr=Ring021([v['id']]);d=rr.data[v['id']];C=canonical(H@d['T']);cam=rr.camera(C,d['Ksmall']);V=rr.curves.V[::17];P=tensor((V-rr.center)/rr.scale);scr=cam.transform_points_screen(P[None],image_size=tensor([[180,320]]))[0,:,:2].detach().cpu().numpy();cn=C.detach().cpu().numpy();p=(V-cn[:3,3])@cn[:3,:3];uv=p@np.asarray(v['K']).T;uv=uv[:,:2]/uv[:,2:];expected=.5*(uv+.5)-.5;err=scr-.5-expected;raw=scr-expected;out=dict(view=v['id'],cad_vertex_samples_N=len(V),source='Original actual CAD and fullRoMa; first FIT view only; no body/HERO/HOLDOUT/GT',OpenCV_native_pixel_center='0-based integer center',resize_pixel_center_formula='u_small=0.5*(u_native+0.5)-0.5',PyTorch3D_screen_to_raster_pixel_center='transform_points_screen returns continuous screen coordinate with raster pixel centers at j+0.5; subtract0.5 for OpenCV-indexed raster array',inherited_Ksmall='K first two rows*0.5 then principal point+0.25; includes renderer halfpixel compensation',actual_screen_minus_halfpixel_to_expected_error_px=stats(np.linalg.norm(err,axis=1)),uncompensated_screen_to_OpenCV_error_px=stats(np.linalg.norm(raw,axis=1)),maximum_component_error_px=float(abs(err).max()),passed=bool(abs(err).max()<1e-3),no_objective_or_input_changed=True);save('metrics/RASTER_PIXEL_CENTER_AUDIT.json',out);print(out,flush=True)
 assert out['passed']
